/**
 * Warna status Surat Diskresi — mengikuti state workflow
 * "Surat Diskresi Data Pengajuan": Draft, Proses Verifikasi Pimcab,
 * Request Approval Ketua, Approved, Rejected, Cancelled.
 */

const STATE_COLOR = {
	Draft: 'gray',
	'Proses Verifikasi Pimcab': 'orange',
	'Request Approval Ketua': 'blue',
	Approved: 'green',
	Rejected: 'red',
	Cancelled: 'red',
}

const PILL = {
	gray: 'bg-ui-surface-gray-100 text-ui-ink-gray-600',
	blue: 'bg-ui-surface-blue-100 text-ui-ink-blue-700',
	orange: 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	green: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	red: 'bg-ui-surface-red-100 text-ui-ink-red-700',
}

export function diskresiPillClass(status) {
	return PILL[STATE_COLOR[status]] || PILL.gray
}

/**
 * Role yang boleh MENGEDIT dokumen per state (kolom Allow Edit di workflow).
 * Draft punya 2 baris state di workflow (CMO & Pimpinan Cabang) → keduanya boleh.
 */
export const STATE_ALLOW_EDIT = {
	Draft: ['CMO', 'Pimpinan Cabang'],
	'Proses Verifikasi Pimcab': ['Pimpinan Cabang'],
	'Request Approval Ketua': ['Director'],
	Approved: ['Administrator'],
	Rejected: ['Administrator'],
	Cancelled: ['Administrator'],
}
